import { monthDates, type District, type PrayerEntry } from './core.js'

export interface PrayerDay {
  entries: PrayerEntry[]
  /** The source's Hijri date for the day; empty when unavailable. */
  hijriDate: string
}

export type ReadResult =
  | {
      status: 'ok'
      /** The day the entries belong to; older when served from a stale cache. */
      date: string
      entries: PrayerEntry[]
      hijriDate: string
      stale: boolean
    }
  | { status: 'unavailable' }

export interface PrayerMonthDay {
  date: string
  entries: PrayerEntry[]
  hijriDate: string
}

export type MonthResult =
  | { status: 'ok'; days: PrayerMonthDay[]; stale: boolean }
  | { status: 'unavailable' }

export interface PrayerRepository {
  /** Cached data first; falls back to the adapter. Never throws to core. */
  read(date: string, district: District): Promise<ReadResult>
  /** Cached days first; fetches the missing ones. Never throws to core. */
  readMonth(month: string, district: District): Promise<MonthResult>
  /**
   * Updates the cache; never blocks rendering; keeps the last good data on
   * failure. Resolves true when fresh data was stored, false otherwise.
   */
  refresh(date: string, district: District): Promise<boolean>
  /** The persisted district selection, or null when missing/corrupt. */
  getSelection(): Promise<District | null>
  setSelection(district: District): Promise<void>
  /**
   * Best-effort synchronous cache view for the first paint of an offline-first
   * shell; null when the store cannot read synchronously or nothing is cached.
   */
  peek?(date: string, district: District): ReadResult | null
  /** Synchronous selection read for the first paint; null when unavailable. */
  getSelectionSync?(): District | null
  /** Synchronous month cache view; null when unavailable or empty. */
  peekMonth?(month: string, district: District): MonthResult | null
}

/** Key/value storage the adapters use; kept vendor-free. */
export interface SelectionStore {
  get(key: string): string | null
  set(key: string, value: string): void
}

export const SELECTION_KEY = 'wsb.selection'

/** Durable day cache behind the port; shells supply device storage. */
export interface PrayerCacheStore {
  get(key: string): Promise<string | null>
  set(key: string, value: string): Promise<void>
  /** Optional synchronous read; lets shells render cached data before paint. */
  getSync?(key: string): string | null
}

// specs/data/spec.md — v4: days now record when they were fetched, and older
// caches had no such stamp, so pre-v4 keys are abandoned instead of being
// served as current forever.
export const DAY_CACHE_PREFIX = 'wsb.day.v4.'
export const LAST_DAY_CACHE_PREFIX = 'wsb.day.last.v4.'

/**
 * specs/data/spec.md — a cached month is revalidated after this long. Months are
 * only refreshed through this TTL, so without it a complete cache would look
 * current forever and miss later corrections.
 */
export const MONTH_CACHE_TTL_MS = 24 * 60 * 60 * 1000

export function dayCacheKey(date: string, district: District): string {
  return `${DAY_CACHE_PREFIX}${date}:${district}`
}

export function lastDayCacheKey(district: District): string {
  return `${LAST_DAY_CACHE_PREFIX}${district}`
}

export interface CachedPrayerData {
  date: string
  district: District
  entries: PrayerEntry[]
  hijriDate: string
  /** Epoch ms when the day was fetched; absent on pre-v4 payloads. */
  fetchedAt?: number
}

/** Remote source behind the port; adapters translate vendor rows to this. */
export interface RemotePrayerSource {
  fetchPrayerEntries(date: string, district: District): Promise<PrayerDay>
  /** Optional bulk read for a month; adapters fall back to per-day reads. */
  fetchPrayerMonth?(
    month: string,
    district: District,
  ): Promise<PrayerMonthDay[]>
}

export interface PrayerRepositoryDeps {
  source: RemotePrayerSource
  /** Device-backed day cache; without it the repository is memory-only. */
  cache?: PrayerCacheStore
  selection?: SelectionStore
  now?: () => Date
}

/**
 * Offline-first prayer repository: device cache, then the remote source.
 * The remote source is Supabase in every shell; MORA is import-time only.
 */
export class CachedPrayerRepository implements PrayerRepository {
  private readonly memory = new Map<string, CachedPrayerData>()
  private readonly source: RemotePrayerSource
  private readonly cache?: PrayerCacheStore
  private readonly selection?: SelectionStore

  constructor(deps: PrayerRepositoryDeps) {
    this.source = deps.source
    this.cache = deps.cache
    this.selection = deps.selection
  }

  peek(date: string, district: District): ReadResult | null {
    const cached =
      this.memory.get(cacheKey(date, district)) ??
      this.peekCache(date, district)
    if (cached) {
      return {
        status: 'ok',
        date: cached.date,
        entries: cached.entries,
        hijriDate: cached.hijriDate,
        stale: false,
      }
    }
    const lastKnown =
      this.lastKnownMemory(district) ?? this.peekLastKnownCache(district)
    return lastKnown
      ? {
          status: 'ok',
          date: lastKnown.date,
          entries: lastKnown.entries,
          hijriDate: lastKnown.hijriDate,
          stale: true,
        }
      : null
  }

  getSelectionSync(): District | null {
    const value = this.selection?.get(SELECTION_KEY) ?? null
    return isKnownDistrict(value) ? value : null
  }

  peekMonth(month: string, district: District): MonthResult | null {
    const dates = monthDates(month)
    const days: PrayerMonthDay[] = []
    for (const date of dates) {
      const cached =
        this.memory.get(cacheKey(date, district)) ??
        this.peekCache(date, district)
      if (cached) days.push(toMonthDay(cached))
    }
    if (days.length === 0) return null
    return { status: 'ok', days, stale: days.length < dates.length }
  }

  async read(date: string, district: District): Promise<ReadResult> {
    const key = cacheKey(date, district)
    const cached = this.memory.get(key) ?? (await this.readCache(date, district))
    if (cached) {
      return {
        status: 'ok',
        date: cached.date,
        entries: cached.entries,
        hijriDate: cached.hijriDate,
        stale: false,
      }
    }

    try {
      const day = await this.source.fetchPrayerEntries(date, district)
      await this.store({ date, district, ...day })
      return {
        status: 'ok',
        date,
        entries: day.entries,
        hijriDate: day.hijriDate,
        stale: false,
      }
    } catch {
      const stale =
        this.lastKnownMemory(district) ?? (await this.lastKnownCache(district))
      return stale
        ? {
            status: 'ok',
            date: stale.date,
            entries: stale.entries,
            hijriDate: stale.hijriDate,
            stale: true,
          }
        : { status: 'unavailable' }
    }
  }

  async refresh(date: string, district: District): Promise<boolean> {
    try {
      const day = await this.source.fetchPrayerEntries(date, district)
      await this.store({ date, district, ...day })
      return true
    } catch {
      // specs/data/spec.md — a failed refresh leaves the previous cache intact.
      return false
    }
  }

  async readMonth(month: string, district: District): Promise<MonthResult> {
    const dates = monthDates(month)
    const days = new Map<string, PrayerMonthDay>()
    const missing: string[] = []
    // Days already shown from cache that are due a refresh.
    const expired = new Set<string>()

    for (const date of dates) {
      const cached =
        this.memory.get(cacheKey(date, district)) ??
        (await this.readCache(date, district))
      if (!cached) {
        missing.push(date)
        continue
      }
      days.set(date, toMonthDay(cached))
      // Specs/data/spec.md — an expired day is served but re-fetched; if the
      // refetch fails it stays in `expired` and the month is marked stale.
      if (isExpired(cached)) {
        missing.push(date)
        expired.add(date)
      }
    }

    if (missing.length > 0) {
      try {
        if (this.source.fetchPrayerMonth) {
          const all = await this.source.fetchPrayerMonth(month, district)
          for (const day of all) {
            if (!dates.includes(day.date)) continue
            days.set(day.date, day)
            expired.delete(day.date)
            await this.store({ ...day, district })
          }
        } else {
          for (const date of missing) {
            try {
              const day = await this.source.fetchPrayerEntries(date, district)
              days.set(date, { date, ...day })
              expired.delete(date)
              await this.store({ date, district, ...day })
            } catch {
              // Keep going: a partial month still renders.
            }
          }
        }
      } catch {
        // specs/data/spec.md — offline or failed: cached days still render.
      }
    }

    if (days.size === 0) return { status: 'unavailable' }
    // specs/data/spec.md — stale means a day is missing or was served from an
    // expired cache entry that could not be refreshed; a complete, recently
    // fetched month is current.
    const stale = days.size < dates.length || expired.size > 0
    return {
      status: 'ok',
      days: dates
        .filter((date) => days.has(date))
        .map((date) => days.get(date)!),
      stale,
    }
  }

  async getSelection(): Promise<District | null> {
    const value = this.selection?.get(SELECTION_KEY) ?? null
    return isKnownDistrict(value) ? value : null
  }

  async setSelection(district: District): Promise<void> {
    this.selection?.set(SELECTION_KEY, district)
  }

  private async store(data: CachedPrayerData): Promise<void> {
    const stamped: CachedPrayerData = { ...data, fetchedAt: Date.now() }
    this.memory.set(cacheKey(data.date, data.district), stamped)
    if (!this.cache) return
    try {
      const payload = JSON.stringify(stamped)
      await this.cache.set(dayCacheKey(data.date, data.district), payload)
      await this.cache.set(lastDayCacheKey(data.district), payload)
    } catch {
      // specs/data/spec.md — cache writes are best-effort; memory still works.
    }
  }

  private peekCache(
    date: string,
    district: District,
  ): CachedPrayerData | undefined {
    if (!this.cache?.getSync) return undefined
    try {
      const raw = this.cache.getSync(dayCacheKey(date, district))
      return raw ? parseCachedDay(raw) : undefined
    } catch {
      return undefined
    }
  }

  private peekLastKnownCache(
    district: District,
  ): CachedPrayerData | undefined {
    if (!this.cache?.getSync) return undefined
    try {
      const raw = this.cache.getSync(lastDayCacheKey(district))
      return raw ? parseCachedDay(raw) : undefined
    } catch {
      return undefined
    }
  }

  private async readCache(
    date: string,
    district: District,
  ): Promise<CachedPrayerData | undefined> {
    if (!this.cache) return undefined
    try {
      const raw = await this.cache.get(dayCacheKey(date, district))
      const parsed = raw ? parseCachedDay(raw) : undefined
      if (parsed) this.memory.set(cacheKey(date, district), parsed)
      return parsed
    } catch {
      return undefined
    }
  }

  private async lastKnownCache(
    district: District,
  ): Promise<CachedPrayerData | undefined> {
    for (const entry of this.memory.values()) {
      if (entry.district === district) return entry
    }
    if (!this.cache) return undefined
    try {
      const raw = await this.cache.get(lastDayCacheKey(district))
      return raw ? parseCachedDay(raw) : undefined
    } catch {
      return undefined
    }
  }

  private lastKnownMemory(district: District): CachedPrayerData | undefined {
    return [...this.memory.values()].find((entry) => entry.district === district)
  }
}

function parseCachedDay(raw: string): CachedPrayerData | undefined {
  try {
    const value = JSON.parse(raw) as Partial<CachedPrayerData>
    if (
      typeof value.date !== 'string' ||
      !isKnownDistrict(value.district ?? null) ||
      !Array.isArray(value.entries) ||
      typeof value.hijriDate !== 'string'
    ) {
      return undefined
    }
    return {
      date: value.date,
      district: value.district as District,
      entries: value.entries,
      hijriDate: value.hijriDate,
      ...(typeof value.fetchedAt === 'number' ? { fetchedAt: value.fetchedAt } : {}),
    }
  } catch {
    return undefined
  }
}

/** True when a cached day is due a refresh (or predates the stamp). */
function isExpired(data: CachedPrayerData): boolean {
  return (
    typeof data.fetchedAt !== 'number' ||
    Date.now() - data.fetchedAt >= MONTH_CACHE_TTL_MS
  )
}

function cacheKey(date: string, district: District): string {
  return `${date}:${district}`
}

function toMonthDay(data: CachedPrayerData): PrayerMonthDay {
  return { date: data.date, entries: data.entries, hijriDate: data.hijriDate }
}

const KNOWN: readonly string[] = ['bruneiMuara', 'tutong', 'belait']

function isKnownDistrict(value: string | null): value is District {
  return value !== null && KNOWN.includes(value)
}
